import numpy as np
def getmasks(A,col=8):
    cells=[(r,c) for r in range(A.shape[0]) for c in range(A.shape[1]) if A[r,c]==col]
    nb=[(-1,0),(1,0),(0,-1),(0,1)]
    seen=set(); res=[]
    for p in cells:
        if p not in seen:
            st=[p]; seen.add(p); comp=[]
            while st:
                q=st.pop(); r,c=q; comp.append((r,c))
                for dr,dc in nb:
                    n=(r+dr,c+dc)
                    if n in cells and n not in seen: seen.add(n); st.append(n)
            rs=[r for r,c in comp]; cs=[c for r,c in comp]
            b=min(rs); l=min(cs)
            g=[[1 if (b+x,l+y) in set(comp) else 0 for y in range(max(cs)-l+1)] for x in range(max(rs)-b+1)]
            res.append((len(comp),g))
    return sorted(res,key=lambda x:x[0])
